            try { Main.readText(missing); System.out.println("no-error"); } catch (java.io.IOException ex) { System.out.println("io-error"); }
        } finally { java.nio.file.Files.deleteIfExists(a); java.nio.file.Files.deleteIfExists(b); }
    }
}

